/*
 * Host test for firmware/common: checks the portable C implementation
 * against vectors/meshfind_vectors.json (generated by the Python reference),
 * then exercises the mesh routing core in a small C-only simulation.
 *
 *   usage: mf_host_test path/to/meshfind_vectors.json
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "json_mini.h"
#include "mf_crypto.h"
#include "mf_mesh.h"
#include "mf_proto.h"

static int g_checks, g_fail;

#define CHECK(cond, ...)                                                    \
    do {                                                                    \
        g_checks++;                                                         \
        if (!(cond)) {                                                      \
            g_fail++;                                                       \
            fprintf(stderr, "FAIL %s:%d: ", __FILE__, __LINE__);            \
            fprintf(stderr, __VA_ARGS__);                                   \
            fprintf(stderr, "\n");                                          \
        }                                                                   \
    } while (0)

#define EQ(a, b, n, what) CHECK(memcmp((a), (b), (n)) == 0, "%s mismatch", what)

static char *slurp(const char *path)
{
    FILE *f = fopen(path, "rb");
    long n;
    char *buf;
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    n = ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = (char *)malloc((size_t)n + 1);
    if (!buf || fread(buf, 1, (size_t)n, f) != (size_t)n) { fclose(f); free(buf); return NULL; }
    buf[n] = 0;
    fclose(f);
    return buf;
}

/* ------------------------------------------------------------ primitives */

static void test_primitives(const jnode *v)
{
    uint8_t a[256], b[256], c[256], d[256], out[256];
    int la, lb, lc;
    for (jnode *e = jget(v, "sha256")->child; e; e = e->next) {
        la = jhex(e, "msg", a, sizeof a);
        jhex(e, "digest", b, sizeof b);
        mf_sha256(a, (size_t)la, out);
        EQ(out, b, 32, "sha256");
    }
    for (jnode *e = jget(v, "hkdf")->child; e; e = e->next) {
        int L = (int)jint(e, "length");
        la = jhex(e, "ikm", a, sizeof a);
        lb = jhex(e, "salt", b, sizeof b);
        lc = jhex(e, "info", c, sizeof c);
        jhex(e, "okm", d, sizeof d);
        CHECK(mf_hkdf_sha256(a, (size_t)la, b, (size_t)lb, c, (size_t)lc, out, (size_t)L) == 0, "hkdf rc");
        EQ(out, d, (size_t)L, "hkdf okm");
    }
    for (jnode *e = jget(v, "x25519")->child; e; e = e->next) {
        jhex(e, "scalar", a, sizeof a);
        jhex(e, "u", b, sizeof b);
        jhex(e, "out", c, sizeof c);
        CHECK(mf_x25519(out, a, b) == 0, "x25519 rc");
        EQ(out, c, 32, "x25519");
    }
    {   /* low-order point must be rejected */
        uint8_t zero[32] = {0}, k[32] = {1};
        CHECK(mf_x25519(out, k, zero) != 0, "x25519 low-order accepted");
    }
    for (jnode *e = jget(v, "aead")->child; e; e = e->next) {
        uint8_t key[32], nonce[12], aad[64], pt[256], ct[272], tag[16], back[256];
        int la2 = jhex(e, "aad", aad, sizeof aad), lp = jhex(e, "pt", pt, sizeof pt), lct;
        jhex(e, "key", key, 32);
        jhex(e, "nonce", nonce, 12);
        lct = jhex(e, "ct", ct, sizeof ct);
        CHECK(lct == lp + 16, "aead vector length");
        mf_aead_encrypt(key, nonce, aad, (size_t)la2, pt, (size_t)lp, out, tag);
        EQ(out, ct, (size_t)lp, "aead ciphertext");
        EQ(tag, ct + lp, 16, "aead tag");
        CHECK(mf_aead_decrypt(key, nonce, aad, (size_t)la2, ct, (size_t)lp, ct + lp, back) == 0, "aead open");
        EQ(back, pt, (size_t)lp, "aead plaintext");
        ct[lp] ^= 1;
        CHECK(mf_aead_decrypt(key, nonce, aad, (size_t)la2, ct, (size_t)lp, ct + lp, back) != 0, "aead tamper");
    }
}

/* ---------------------------------------------------------------- protocol */

static void test_ratchet(const jnode *v)
{
    const jnode *r = jget(v, "ratchet");
    uint8_t master[32], pk[32], tmp[32], out[32];
    mf_tag_state_t st;
    uint32_t epoch0 = (uint32_t)jint(r, "epoch0");
    jhex(r, "master", master, 32);
    jhex(r, "presence_key", pk, 32);
    mf_presence_key(master, out);
    EQ(out, pk, 32, "presence key");
    mf_tag_provision(&st, master, epoch0, (uint32_t)jint(r, "epoch_seconds"));
    for (jnode *e = jget(r, "epochs")->child; e; e = e->next) {
        uint32_t idx = (uint32_t)jint(e, "index");
        uint8_t sk[32], priv[32], pub[32], hash[32];
        jhex(e, "sk", sk, 32);
        jhex(e, "priv", priv, 32);
        jhex(e, "pub", pub, 32);
        jhex(e, "hash", hash, 32);
        CHECK(mf_tag_advance(&st, idx) == MF_OK, "advance");
        EQ(st.sk, sk, 32, "chain sk");
        mf_epoch_private(st.sk, out);
        EQ(out, priv, 32, "epoch priv");
        CHECK(mf_epoch_public(st.sk, out) == MF_OK, "epoch pub rc");
        EQ(out, pub, 32, "epoch pub");
        mf_key_hash(pub, out);
        EQ(out, hash, 32, "key hash");
        /* the tag-side API derives the same key from wall-clock time */
        {
            mf_tag_state_t t2;
            mf_tag_provision(&t2, master, epoch0, 900);
            CHECK(mf_tag_current_public(&t2, epoch0 + idx * 900 + 451, false, out) == MF_OK, "current pub");
            EQ(out, pub, 32, "current pub");
        }
    }
    CHECK(mf_tag_advance(&st, 3) == MF_ERR_ARG, "ratchet went backwards");
    for (jnode *e = jget(r, "separated")->child; e; e = e->next) {
        uint32_t idx = (uint32_t)jint(e, "index");
        uint8_t sk[32], pub[32];
        jhex(e, "sk", sk, 32);
        jhex(e, "pub", pub, 32);
        CHECK(mf_tag_advance_sep(&st, idx) == MF_OK, "advance sep");
        EQ(st.sep_sk, sk, 32, "sep chain sk");
        mf_epoch_public(st.sep_sk, out);
        EQ(out, pub, 32, "sep pub");
    }
    for (jnode *e = jget(r, "presence")->child; e; e = e->next) {
        uint8_t tok[16];
        jhex(e, "token", tok, 16);
        uint8_t advb[64], mine[MF_PRESENCE_ADV_LEN];
        uint32_t ep = (uint32_t)jint(e, "epoch"), found = 0;
        int la = jhex(e, "adv", advb + 3, sizeof advb - 3);
        mf_presence_token(pk, ep, tmp);
        EQ(tmp, tok, 16, "presence token");
        mf_presence_encode(tok, mine);
        CHECK(la == MF_PRESENCE_ADV_LEN, "presence adv length");
        EQ(mine, advb + 3, MF_PRESENCE_ADV_LEN, "presence adv");
        advb[0] = 2; advb[1] = 0x01; advb[2] = 0x06; /* a Flags AD before it */
        CHECK(mf_presence_find(pk, advb, (size_t)la + 3, ep + 3, 4, &found) == MF_OK && found == ep, "presence find");
        CHECK(mf_presence_find(pk, advb, (size_t)la + 3, ep + 10, 4, &found) != MF_OK, "stale presence accepted");
        advb[10] ^= 1;
        CHECK(mf_presence_find(pk, advb, (size_t)la + 3, ep, 4, &found) != MF_OK, "forged presence accepted");
    }
    for (jnode *e = jget(v, "epoch_index")->child; e; e = e->next) {
        uint32_t idx = 0;
        CHECK(mf_epoch_index((uint32_t)jint(e, "t"), (uint32_t)jint(e, "epoch0"), (uint32_t)jint(e, "seconds"), &idx) == MF_OK, "epoch idx rc");
        CHECK(idx == (uint32_t)jint(e, "index"), "epoch index %u", idx);
    }
    {
        uint32_t idx;
        CHECK(mf_epoch_index(epoch0 - 1, epoch0, 900, &idx) == MF_ERR_TIME, "time before epoch0");
    }
}

static void test_adv(const jnode *v)
{
    for (jnode *e = jget(v, "adv")->child; e; e = e->next) {
        mf_adv_t a, d;
        uint8_t addr[6], pl[31], eaddr[6], epl[31];
        jhex(e, "pub", a.pub, 32);
        a.battery = (uint8_t)jint(e, "battery");
        a.separated = jint(e, "separated") != 0;
        jhex(e, "addr", eaddr, 6);
        jhex(e, "payload", epl, 31);
        CHECK(mf_adv_encode(&a, addr, pl) == MF_OK, "adv encode rc");
        EQ(addr, eaddr, 6, "adv address");
        EQ(pl, epl, 31, "adv payload");
        CHECK(mf_adv_decode(addr, pl, 31, &d) == MF_OK, "adv decode rc");
        EQ(d.pub, a.pub, 32, "adv decoded key");
        CHECK(d.battery == a.battery && d.separated == a.separated, "adv decoded status");
        CHECK(mf_adv_decode(addr, pl, 30, &d) != MF_OK, "adv short accepted");
        pl[2] = 0x4C;
        CHECK(mf_adv_decode(addr, pl, 31, &d) != MF_OK, "adv foreign company accepted");
        pl[2] = 0xFF;
        addr[0] &= 0x3F;
        CHECK(mf_adv_decode(addr, pl, 31, &d) != MF_OK, "adv non-static address accepted");
    }
    for (jnode *e = jget(v, "adv_interval")->child; e; e = e->next) {
        uint32_t ms = mf_adv_interval_ms((int)jint(e, "percent"), jint(e, "separated") != 0);
        CHECK(ms == (uint32_t)jint(e, "ms"), "adv interval %u", ms);
    }
}

static void test_report(const jnode *v)
{
    for (jnode *e = jget(v, "report")->child; e; e = e->next) {
        uint8_t pub[32], priv[32], eph[32], pt[26], env[MF_ENVELOPE_LEN], out[MF_ENVELOPE_LEN], ptc[26];
        mf_sighting_t s, o;
        jhex(e, "tag_pub", pub, 32);
        jhex(e, "tag_priv", priv, 32);
        jhex(e, "eph_secret", eph, 32);
        jhex(e, "plaintext", pt, 26);
        CHECK(jhex(e, "envelope", env, sizeof env) == MF_ENVELOPE_LEN, "envelope length");
        memset(&s, 0, sizeof s);
        s.version = 1;
        s.flags = (uint8_t)jint(e, "flags");
        s.seen_ts = (uint32_t)jint(e, "seen_ts");
        s.node_id = (uint32_t)jint(e, "node_id");
        s.x = (int32_t)jint(e, "x");
        s.y = (int32_t)jint(e, "y");
        s.z = (int32_t)jint(e, "z");
        s.accuracy_cm = (uint16_t)jint(e, "accuracy_cm");
        s.rssi = (int8_t)jint(e, "rssi");
        s.tag_status = (uint8_t)jint(e, "tag_status");
        mf_sighting_pack(&s, ptc);
        EQ(ptc, pt, 26, "plaintext pack");
        CHECK(mf_report_seal(pub, &s, eph, out) == MF_OK, "seal rc");
        EQ(out, env, MF_ENVELOPE_LEN, "sealed envelope");
        CHECK(mf_report_open(priv, pub, env, &o) == MF_OK, "open rc");
        CHECK(memcmp(&o, &s, sizeof s) == 0 || (o.seen_ts == s.seen_ts && o.x == s.x && o.rssi == s.rssi &&
                                                 o.node_id == s.node_id && o.tag_status == s.tag_status),
              "opened sighting");
        for (int i = 0; i < MF_ENVELOPE_LEN; i++) { /* every byte is authenticated */
            env[i] ^= 0x01;
            CHECK(mf_report_open(priv, pub, env, &o) != MF_OK, "tampered byte %d accepted", i);
            env[i] ^= 0x01;
        }
    }
    {
        uint8_t zero[32] = {0}, eph[32] = {7}, out[MF_ENVELOPE_LEN];
        mf_sighting_t s = {1, 3, 0, 0, 0, 0, 0, 0, 0, 0};
        CHECK(mf_report_seal(zero, &s, eph, out) == MF_ERR_KEY, "low-order tag key accepted");
    }
}

static void test_mesh_vectors(const jnode *v)
{
    for (jnode *e = jget(v, "mesh_frames")->child; e; e = e->next) {
        uint8_t pl[200], enc[260], mid[8], out[260];
        size_t n = 0;
        mf_frame_t f, d;
        int lp = jhex(e, "payload", pl, sizeof pl), le = jhex(e, "encoded", enc, sizeof enc);
        jhex(e, "msg_id", mid, 8);
        f.type = (uint8_t)jint(e, "type");
        f.ttl = (uint8_t)jint(e, "ttl");
        f.sender_dist = (uint8_t)jint(e, "sender_dist");
        memcpy(f.msg_id, mid, 8);
        f.payload = pl;
        f.payload_len = (size_t)lp;
        CHECK(mf_frame_encode(&f, out, sizeof out, &n) == MF_OK && n == (size_t)le, "frame encode");
        EQ(out, enc, (size_t)le, "frame bytes");
        CHECK(mf_frame_decode(enc, (size_t)le, &d) == MF_OK, "frame decode");
        CHECK(d.type == f.type && d.ttl == f.ttl && d.sender_dist == f.sender_dist && d.payload_len == f.payload_len,
              "frame fields");
        if (f.type == MF_T_REPORT) {
            mf_report_msg_id(pl, out);
            EQ(out, mid, 8, "report msg id");
        }
        if (f.type == MF_T_BEACON) {
            uint32_t gw, seq, ut;
            mf_beacon_parse(pl, &gw, &seq, &ut);
            mf_beacon_msg_id(gw, seq, out);
            EQ(out, mid, 8, "beacon msg id");
        }
        CHECK(mf_frame_decode(enc, (size_t)le - 1, &d) != MF_OK || f.type == MF_T_ACK, "truncated frame accepted");
    }
    for (jnode *e = jget(v, "mesh_forward")->child; e; e = e->next) {
        bool got = mf_mesh_should_forward(jint(e, "is_gateway") != 0, (uint8_t)jint(e, "my_dist"),
                                          (uint8_t)jint(e, "sender_dist"), (uint8_t)jint(e, "ttl"));
        CHECK(got == (jint(e, "forward") != 0), "should_forward(%lld,%lld,%lld,%lld)", jint(e, "is_gateway"),
              jint(e, "my_dist"), jint(e, "sender_dist"), jint(e, "ttl"));
    }
}

/* ------------------------------------------------------- C mesh simulation */

#define SIM_MAX 48
typedef struct {
    int n;
    double x[SIM_MAX], y[SIM_MAX];
    mf_mesh_node_t node[SIM_MAX];
    uint8_t delivered[512][8];
    int ndelivered;
    uint64_t rng;
    double range, loss;
} sim_t;

static uint32_t xr(void *ctx)
{
    uint64_t *s = (uint64_t *)ctx;
    *s ^= *s << 13;
    *s ^= *s >> 7;
    *s ^= *s << 17;
    return (uint32_t)(*s >> 16);
}

static void sim_deliver(void *ctx, const uint8_t env[MF_ENVELOPE_LEN])
{
    sim_t *s = (sim_t *)ctx;
    uint8_t id[8];
    mf_report_msg_id(env, id);
    for (int i = 0; i < s->ndelivered; i++)
        if (!memcmp(s->delivered[i], id, 8)) return;
    if (s->ndelivered < 512) memcpy(s->delivered[s->ndelivered++], id, 8);
}

typedef struct { int dst; uint8_t buf[MF_MESH_MAX_FRAME]; size_t len; } inflight_t;
static inflight_t g_air[8192];

static void sim_run(sim_t *s, uint32_t *now, uint32_t ms, uint32_t *next_beacon)
{
    int nair = 0;
    for (uint32_t t = 0; t < ms; t += 50) {
        int cur = nair;
        static inflight_t batch[8192];
        memcpy(batch, g_air, sizeof(inflight_t) * (size_t)cur);
        nair = 0;
        *now += 50;
        for (int i = 0; i < cur; i++) mf_mesh_on_rx(&s->node[batch[i].dst], batch[i].buf, batch[i].len, *now);
        if ((int32_t)(*now - *next_beacon) >= 0) {
            for (int i = 0; i < s->n; i++)
                if (s->node[i].is_gateway) mf_mesh_emit_beacon(&s->node[i], 1767225600u + *now / 1000, *now);
            *next_beacon = *now + 10000;
        }
        for (int i = 0; i < s->n; i++) {
            uint8_t out[MF_MESH_MAX_FRAME];
            size_t len;
            while ((len = mf_mesh_poll(&s->node[i], *now, out, sizeof out)) > 0) {
                for (int j = 0; j < s->n; j++) {
                    double dx = s->x[i] - s->x[j], dy = s->y[i] - s->y[j];
                    if (j == i || dx * dx + dy * dy > s->range * s->range) continue;
                    if ((xr(&s->rng) % 10000) < (uint32_t)(s->loss * 10000)) continue;
                    if (nair < 8192) {
                        g_air[nair].dst = j;
                        memcpy(g_air[nair].buf, out, len);
                        g_air[nair].len = len;
                        nair++;
                    }
                }
            }
        }
    }
}

static void sim_init(sim_t *s, int n, int gws, double range, double loss, uint64_t seed)
{
    memset(s, 0, sizeof *s);
    s->n = n;
    s->range = range;
    s->loss = loss;
    s->rng = seed;
    for (int i = 0; i < n; i++)
        mf_mesh_init(&s->node[i], 0x100u + (uint32_t)i, i < gws, NULL, xr, &s->rng, sim_deliver, s);
}

static void fake_env(uint8_t env[MF_ENVELOPE_LEN], uint64_t *rng)
{
    env[0] = 1;
    env[1] = 0;
    for (int i = 2; i < MF_ENVELOPE_LEN; i++) env[i] = (uint8_t)xr(rng);
}

static void test_mesh_units(void)
{
    mf_dedup_t d;
    mf_bucket_t b;
    uint8_t a[8] = {1}, c[8] = {2};
    mf_dedup_init(&d, 1000);
    CHECK(!mf_dedup_seen(&d, a, 0) && mf_dedup_seen(&d, a, 10), "dedup basic");
    CHECK(!mf_dedup_seen(&d, a, 2000), "dedup expiry");
    CHECK(!mf_dedup_seen(&d, c, 2000), "dedup other id");
    mf_bucket_init(&b, 2, 3);
    CHECK(mf_bucket_take(&b, 0) && mf_bucket_take(&b, 0) && mf_bucket_take(&b, 0) && !mf_bucket_take(&b, 0), "bucket burst");
    CHECK(mf_bucket_take(&b, 500) && !mf_bucket_take(&b, 500), "bucket refill");

    {   /* per-key origination limit */
        mf_mesh_node_t n;
        uint64_t r = 99;
        uint8_t env[MF_ENVELOPE_LEN];
        fake_env(env, &r);
        mf_mesh_init(&n, 1, false, NULL, xr, &r, NULL, NULL);
        CHECK(mf_mesh_originate(&n, env, 0), "originate");
        env[100] ^= 1; /* same key hash, different report */
        CHECK(!mf_mesh_originate(&n, env, 1000), "origin rate limit");
        CHECK(mf_mesh_originate(&n, env, 301000), "origin after interval");
    }
}

static sim_t g_sim;

static void test_mesh_line(void)
{
    sim_t *s = &g_sim;
    uint32_t now = 0, nb = 0, ut = 0;
    uint8_t env[MF_ENVELOPE_LEN];
    sim_init(s, 4, 1, 1.5, 0.0, 12345);
    for (int i = 0; i < 4; i++) { s->x[i] = i; s->y[i] = 0; }
    sim_run(s, &now, 5000, &nb);
    for (int i = 0; i < 4; i++) CHECK(mf_mesh_dist(&s->node[i], now) == i, "line dist node %d = %u", i, mf_mesh_dist(&s->node[i], now));
    CHECK(mf_mesh_unix_time(&s->node[3], now, &ut) && ut >= 1767225600u, "time sync from beacons");
    fake_env(env, &s->rng);
    mf_mesh_originate(&s->node[3], env, now);
    sim_run(s, &now, 5000, &nb);
    CHECK(s->ndelivered == 1, "line delivery (%d)", s->ndelivered);
    for (int i = 0; i < 4; i++) {
        int pending = 0;
        for (int k = 0; k < MF_QUEUE_SLOTS; k++) pending += s->node[i].q[k].used && s->node[i].q[k].needs_ack;
        CHECK(pending == 0, "node %d still retrying after ack", i);
    }
}

static void test_mesh_random(double loss, uint64_t seed)
{
    sim_t *s = &g_sim;
    uint32_t now = 0, nb = 0;
    int orig = 0;
    uint64_t pr = seed * 7919 + 1;
    /* random geometric graph; retry until connected */
    for (int attempt = 0; attempt < 200; attempt++) {
        int seen[SIM_MAX] = {1}, stack[SIM_MAX], sp = 0, cnt = 1;
        sim_init(s, 40, 2, 45.0, loss, seed);
        for (int i = 0; i < 40; i++) { s->x[i] = xr(&pr) % 20000 / 100.0; s->y[i] = xr(&pr) % 20000 / 100.0; }
        stack[sp++] = 0;
        while (sp) {
            int i = stack[--sp];
            for (int j = 0; j < 40; j++) {
                double dx = s->x[i] - s->x[j], dy = s->y[i] - s->y[j];
                if (!seen[j] && dx * dx + dy * dy <= 45.0 * 45.0) { seen[j] = 1; cnt++; stack[sp++] = j; }
            }
        }
        if (cnt == 40) break;
    }
    sim_run(s, &now, 30000, &nb);
    for (int i = 2; i < 40; i++) {
        uint8_t env[MF_ENVELOPE_LEN];
        fake_env(env, &s->rng);
        orig += mf_mesh_originate(&s->node[i], env, now);
    }
    sim_run(s, &now, 60000, &nb);
    CHECK(s->ndelivered * 100 >= orig * 95, "random mesh loss=%.1f delivered %d/%d", loss, s->ndelivered, orig);
    printf("  C mesh sim: loss %.0f%% -> delivered %d/%d\n", loss * 100, s->ndelivered, orig);
}

int main(int argc, char **argv)
{
    char *src;
    jnode *v;
    if (argc < 2) {
        fprintf(stderr, "usage: %s meshfind_vectors.json\n", argv[0]);
        return 2;
    }
    src = slurp(argv[1]);
    if (!src || !(v = jparse(src))) {
        fprintf(stderr, "cannot read/parse %s\n", argv[1]);
        return 2;
    }
    test_primitives(v);
    test_ratchet(v);
    test_adv(v);
    test_report(v);
    test_mesh_vectors(v);
    test_mesh_units();
    test_mesh_line();
    test_mesh_random(0.1, 1);
    test_mesh_random(0.2, 2);
    test_mesh_random(0.3, 3);
    printf("%d checks, %d failures\n", g_checks, g_fail);
    return g_fail ? 1 : 0;
}
